1	package govflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"sync"
15		"syscall"
16	)
17	
18	// 资金库状态文件相关错误。
19	var (
20		// ErrTreasuryAlreadyInit：初始化目标路径已存在文件，新文件才能初始化。
21		ErrTreasuryAlreadyInit = errors.New("treasury init refused: state file already exists")
22		// ErrStateCorrupt：状态文件损坏或不是受支持的资金库状态文件。
23		ErrStateCorrupt = errors.New("treasury state file is corrupt")
24		// ErrProposalNotFound：按编号查询或执行时提案不存在。
25		ErrProposalNotFound = errors.New("proposal not found")
26		// ErrProposalConflict：同编号提案再次登记但时间锁或动作原文与首次不同。
27		ErrProposalConflict = errors.New("proposal already registered with different timelock or actions")
28		// ErrInvalidRegistration：登记参数非法（编号为空、初始余额越界等）。
29		ErrInvalidRegistration = errors.New("invalid registration")
30	)
31	
32	const (
33		stateMagic   = "govflow-treasury-state"
34		stateVersion = 1
35		lockSuffix   = ".lock"
36	)
37	
38	// BalanceUpdate 记录一个账户在一次动作前后的余额。
39	type BalanceUpdate struct {
40		Account string `json:"account"`
41		Before  int64  `json:"before"`
42		After   int64  `json:"after"`
43	}
44	
45	// ActionReceipt 是凭据中对单项动作的留痕：动作原文、在提案中的顺序编号（0 起），
46	// 以及该动作引发的资金库与收款账户余额变动。
47	type ActionReceipt struct {
48		Index     int           `json:"index"`
49		Action    string        `json:"action"`
50		Treasury  BalanceUpdate `json:"treasury"`
51		Recipient BalanceUpdate `json:"recipient"`
52	}
53	
54	// Receipt 是一项提案首次成功执行后生成的执行凭据。
55	// 一项提案只允许成功一次；重试返回同一份凭据。
56	type Receipt struct {
57		ProposalID string          `json:"proposal_id"`
58		ExecutedAt int64           `json:"executed_at"` // 首次成功执行时调用方提供的时间
59		Order      int             `json:"order"`       // 成功提交的先后顺序，0 起
60		Actions    []ActionReceipt `json:"actions"`
61	}
62	
63	// ProposalRecord 是已登记提案的对外视图。State 只可能是 passed 或 executed。
64	type ProposalRecord struct {
65		ID          string   `json:"id"`
66		State       string   `json:"state"`
67		TimelockEnd int64    `json:"timelock_end"`
68		Actions     []string `json:"actions"`
69	}
70	
71	// ---- 磁盘结构（JSON） ----
72	
73	type storedProposal struct {
74		ID          string   `json:"id"`
75		State       string   `json:"state"`
76		TimelockEnd int64    `json:"timelock_end"`
77		Actions     []string `json:"actions"`
78	}
79	
80	type storedState struct {
81		Magic           string                     `json:"magic"`
82		Version         int                        `json:"version"`
83		InitialTreasury int64                      `json:"initial_treasury"`
84		Treasury        int64                      `json:"treasury"`
85		Balances        map[string]int64           `json:"balances"`
86		Proposals       map[string]*storedProposal `json:"proposals"`
87		Receipts        []*Receipt                 `json:"receipts"`
88	}
89	
90	// Store 是绑定到单个本地状态文件的资金库句柄。
91	// 多个 goroutine 可并发使用同一个 Store；不同 Store/进程操作同一状态文件时，
92	// 通过进程内互斥锁与文件锁（flock）串行化。
93	type Store struct {
94		path   string
95		mu     sync.Mutex // 保护本句柄上的全部操作
96		lockFD *os.File   // 跨进程文件锁
97		closed bool
98	}
99	
100	// 进程内按规范路径共享的互斥锁，保证同进程内多个 Store 句柄也互相串行。
101	var (
102		pathLocksMu sync.Mutex
103		pathLocks   = map[string]*sync.Mutex{}
104	)
105	
106	// canonicalPath 将路径规范化为绝对路径，保证不同拼写（如 t.json 与 ./t.json）
107	// 命中同一把进程内锁与同一个锁文件。有意不解析符号链接：文件在初始化前后必须
108	// 解析到同一个键，硬链接/绑定挂载等更深层别名不在本地单文件场景的处理范围内。
109	func canonicalPath(path string) (string, error) {
110		return filepath.Abs(path)
111	}
112	
113	func inProcessLock(path string) *sync.Mutex {
114		pathLocksMu.Lock()
115		defer pathLocksMu.Unlock()
116		m, ok := pathLocks[path]
117		if !ok {
118			m = &sync.Mutex{}
119			pathLocks[path] = m
120		}
121		return m
122	}
123	
124	// InitTreasury 创建一个全新的状态文件并写入初始资金库余额。
125	// 只有新文件才能初始化：路径已存在（含损坏文件）一律拒绝，不会重置或覆盖。
126	// treasury 必须落在有符号 64 位整数范围内且不得为负。
127	func InitTreasury(path string, treasury int64) (*Store, error) {
128		if treasury < 0 {
129			return nil, fmt.Errorf("%w: initial treasury balance must not be negative", ErrInvalidRegistration)
130		}
131		path, err := canonicalPath(path)
132		if err != nil {
133			return nil, err
134		}
135		pathMu := inProcessLock(path)
136		pathMu.Lock()
137		defer pathMu.Unlock()
138	
139		// 先打开/创建锁文件并取跨进程锁，再创建状态文件，消除“空文件已出现、
140		// 尚未写入”期间被其它进程 Open 判为损坏的窗口。
141		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
142		if err != nil {
143			return nil, err
144		}
145		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
146			_ = lockFD.Close()
147			return nil, err
148		}
149		// O_EXCL 保证与并发初始化竞争时只有一方成功。
150		fd, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
151		if err != nil {
152			_ = syscall.Flock(int(lockFD.Fd()), syscall.LOCK_UN)
153			_ = lockFD.Close()
154			if errors.Is(err, fs.ErrExist) {
155				return nil, fmt.Errorf("%w: %s", ErrTreasuryAlreadyInit, path)
156			}
157			return nil, err
158		}
159		_ = fd.Close()
160	
161		store := &Store{path: path, lockFD: lockFD}
162		if err := store.commitLocked(newStoredState(treasury)); err != nil {
163			_ = store.funlock()
164			_ = lockFD.Close()
165			_ = os.Remove(path)
166			return nil, err
167		}
168		// 初始化完成后立即释放跨进程锁；后续每次操作各自短持锁。
169		if err := store.funlock(); err != nil {
170			_ = lockFD.Close()
171			_ = os.Remove(path)
172			return nil, err
173		}
174		return store, nil
175	}
176	
177	// Open 打开已有的资金库状态文件。文件损坏时明确拒绝，不会重建或覆盖原文件。
178	func Open(path string) (*Store, error) {
179		path, err := canonicalPath(path)
180		if err != nil {
181			return nil, err
182		}
183		pathMu := inProcessLock(path)
184		pathMu.Lock()
185		defer pathMu.Unlock()
186		return openStoreHoldingPathLock(path)
187	}
188	
189	// openStoreHoldingPathLock 的调用方必须持有该路径的进程内互斥锁。
190	func openStoreHoldingPathLock(path string) (*Store, error) {
191		if _, err := os.Stat(path); err != nil {
192			return nil, err
193		}
194		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
195		if err != nil {
196			return nil, err
197		}
198		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
199			_ = lockFD.Close()
200			return nil, err
201		}
202		store := &Store{path: path, lockFD: lockFD}
203		if _, err := store.loadLocked(); err != nil {
204			_ = store.funlock()
205			_ = lockFD.Close()
206			return nil, err
207		}
208		// 打开时已做严格校验；锁随即释放，每次操作再各自短持锁。
209		if err := store.funlock(); err != nil {
210			_ = lockFD.Close()
211			return nil, err
212		}
213		return store, nil
214	}
215	
216	// Path 返回状态文件路径。
217	func (s *Store) Path() string { return s.path }
218	
219	// Close 释放文件锁。关闭后其它操作返回错误。
220	func (s *Store) Close() error {
221		s.mu.Lock()
222		defer s.mu.Unlock()
223		if s.closed {
224			return nil
225		}
226		s.closed = true
227		if err := s.funlock(); err != nil {
228			_ = s.lockFD.Close()
229			return err
230		}
231		return s.lockFD.Close()
232	}
233	
234	func (s *Store) flock(how int) error {
235		if s.lockFD == nil {
236			return errors.New("treasury store is closed")
237		}
238		return syscall.Flock(int(s.lockFD.Fd()), how)
239	}
240	
241	func (s *Store) funlock() error {
242		if s.lockFD == nil {
243			return nil
244		}
245		return syscall.Flock(int(s.lockFD.Fd()), syscall.LOCK_UN)
246	}
247	
248	// begin 串行化一次读改写操作：先取进程内路径锁，再取跨进程排他文件锁。
249	// 返回的 commit 在操作结束时释放锁。
250	func (s *Store) begin() (func(), error) {
251		pathMu := inProcessLock(s.path)
252		pathMu.Lock()
253		s.mu.Lock()
254		if s.closed {
255			s.mu.Unlock()
256			pathMu.Unlock()
257			return nil, errors.New("treasury store is closed")
258		}
259		if err := s.flock(syscall.LOCK_EX); err != nil {
260			s.mu.Unlock()
261			pathMu.Unlock()
262			return nil, err
263		}
264		return func() {
265			_ = s.funlock()
266			s.mu.Unlock()
267			pathMu.Unlock()
268		}, nil
269	}
270	
271	func newStoredState(treasury int64) *storedState {
272		return &storedState{
273			Magic:           stateMagic,
274			Version:         stateVersion,
275			InitialTreasury: treasury,
276			Treasury:        treasury,
277			Balances:        map[string]int64{},
278			Proposals:       map[string]*storedProposal{},
279			Receipts:        []*Receipt{},
280		}
281	}
282	
283	// ---- 登记 ----
284	
285	// Register 登记一项已通过（passed）的提案，保留时间锁与动作原文。
286	// 编号必须非空；动作列表可为空（执行时会因动作为空被拒绝），动作原文不做改写。
287	// 同编号且时间锁、动作原文与首次登记完全相同的重试返回 existed=true；
288	// 内容不同则返回 ErrProposalConflict。
289	func (s *Store) Register(id string, timelockEnd int64, actions []string) (existed bool, err error) {
290		if id == "" {
291			return false, fmt.Errorf("%w: proposal id must not be empty", ErrInvalidRegistration)
292		}
293		commit, err := s.begin()
294		if err != nil {
295			return false, err
296		}
297		defer commit()
298	
299		state, err := s.loadLocked()
300		if err != nil {
301			return false, err
302		}
303		stored := copyActions(actions)
304		if existing, ok := state.Proposals[id]; ok {
305			if existing.TimelockEnd == timelockEnd && sameActions(existing.Actions, stored) {
306				return true, nil
307			}
308			return false, fmt.Errorf("%w: proposal %s", ErrProposalConflict, id)
309		}
310		state.Proposals[id] = &storedProposal{
311			ID:          id,
312			State:       "passed",
313			TimelockEnd: timelockEnd,
314			Actions:     stored,
315		}
316		if err := s.commitLocked(state); err != nil {
317			return false, err
318		}
319		return false, nil
320	}
321	
322	func copyActions(actions []string) []string {
323		if actions == nil {
324			return nil
325		}
326		copied := make([]string, len(actions))
327		copy(copied, actions)
328		return copied
329	}
330	
331	// sameActions 将 nil 与空切片视为等价，其余按顺序逐字比较。
332	func sameActions(a, b []string) bool {
333		if len(a) != len(b) {
334			return false
335		}
336		for i := range a {
337			if a[i] != b[i] {
338				return false
339			}
340		}
341		return true
342	}
343	
344	// ---- 执行 ----
345	
346	// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
347	// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
348	// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
349	// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
350	// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
351	func (s *Store) Execute(id string, now int64) (*Receipt, error) {
352		commit, err := s.begin()
353		if err != nil {
354			return nil, err
355		}
356		defer commit()
357	
358		state, err := s.loadLocked()
359		if err != nil {
360			return nil, err
361		}
362		proposal, ok := state.Proposals[id]
363		if !ok {
364			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
365		}
366		if proposal.State == "executed" {
367			if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
368				return cloneReceipt(rcpt), nil
369			}
370			return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
371		}
372		if proposal.State != "passed" {
373			return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, proposal.State))
374		}
375		if now < proposal.TimelockEnd {
376			return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, proposal.TimelockEnd))
377		}
378		if len(proposal.Actions) == 0 {
379			return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
380		}
381	
382		// 第一阶段：在副本上校验并预演全部动作。任何一步失败都不得落盘。
383		type step struct {
384			account        string
385			amount         int64
386			treasuryBefore int64
387			treasuryAfter  int64
388			accountBefore  int64
389			accountAfter   int64
390		}
391		simTreasury := state.Treasury
392		simBalances := map[string]int64{}
393		for k, v := range state.Balances {
394			simBalances[k] = v
395		}
396		steps := make([]step, 0, len(proposal.Actions))
397		for i, raw := range proposal.Actions {
398			account, amount, perr := ParseTransfer(raw)
399			if perr != nil {
400				// 双 %w：调用方既可按 ErrExecutionRejected 判定执行被拒，
401				// 也可按 ErrInvalidAction 区分“动作格式错误”这一具体原因。
402				return nil, fmt.Errorf("%w: action %d (%q): %w", ErrExecutionRejected, i, raw, perr)
403			}
404			balanceBefore := simBalances[account]
405			balanceAfter, ok := addInt64(balanceBefore, amount)
406			if !ok {
407				return nil, execReject(fmt.Sprintf("recipient balance overflow at action %d: account=%s balance=%d amount=%d", i, account, balanceBefore, amount))
408			}
409			if simTreasury < amount {
410				return nil, execReject(fmt.Sprintf("insufficient treasury balance at action %d: treasury=%d amount=%d", i, simTreasury, amount))
411			}
412			treasuryBefore := simTreasury
413			simTreasury -= amount
414			simBalances[account] = balanceAfter
415			steps = append(steps, step{
416				account:        account,
417				amount:         amount,
418				treasuryBefore: treasuryBefore,
419				treasuryAfter:  simTreasury,
420				accountBefore:  balanceBefore,
421				accountAfter:   balanceAfter,
422			})
423		}
424	
425		// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
426		receipt := &Receipt{
427			ProposalID: id,
428			ExecutedAt: now,
429			Order:      len(state.Receipts),
430			Actions:    make([]ActionReceipt, 0, len(steps)),
431		}
432		for i, st := range steps {
433			receipt.Actions = append(receipt.Actions, ActionReceipt{
434				Index:  i,
435				Action: proposal.Actions[i],
436				Treasury: BalanceUpdate{
437					Account: "treasury",
438					Before:  st.treasuryBefore,
439					After:   st.treasuryAfter,
440				},
441				Recipient: BalanceUpdate{
442					Account: st.account,
443					Before:  st.accountBefore,
444					After:   st.accountAfter,
445				},
446			})
447		}
448		state.Treasury = simTreasury
449		state.Balances = simBalances
450		proposal.State = "executed"
451		state.Receipts = append(state.Receipts, receipt)
452	
453		if err := s.commitLocked(state); err != nil {
454			return nil, err
455		}
456		return cloneReceipt(receipt), nil
457	}
458	
459	func findReceipt(receipts []*Receipt, id string) *Receipt {
460		for _, r := range receipts {
461			if r.ProposalID == id {
462				return r
463			}
464		}
465		return nil
466	}
467	
468	func cloneReceipt(r *Receipt) *Receipt {
469		if r == nil {
470			return nil
471		}
472		copied := *r
473		if r.Actions != nil {
474			copied.Actions = make([]ActionReceipt, len(r.Actions))
475			copy(copied.Actions, r.Actions)
476		}
477		return &copied
478	}
479	
480	// ---- 查询 ----
481	
482	// TreasuryBalance 返回资金库当前余额。
483	func (s *Store) TreasuryBalance() (int64, error) {
484		state, err := s.readState()
485		if err != nil {
486			return 0, err
487		}
488		return state.Treasury, nil
489	}
490	
491	// Balance 返回收款账户余额；从未出现过的账户余额为零。
492	func (s *Store) Balance(account string) (int64, error) {
493		state, err := s.readState()
494		if err != nil {
495			return 0, err
496		}
497		return state.Balances[account], nil
498	}
499	
500	// Balances 返回全部出现过的收款账户余额的副本，按账户名排序。
501	func (s *Store) Balances() (map[string]int64, error) {
502		state, err := s.readState()
503		if err != nil {
504			return nil, err
505		}
506		out := make(map[string]int64, len(state.Balances))
507		for k, v := range state.Balances {
508			out[k] = v
509		}
510		return out, nil
511	}
512	
513	// Proposal 按编号返回提案登记信息；不存在时 ok 为 false。
514	func (s *Store) Proposal(id string) (ProposalRecord, bool, error) {
515		state, err := s.readState()
516		if err != nil {
517			return ProposalRecord{}, false, err
518		}
519		p, ok := state.Proposals[id]
520		if !ok {
521			return ProposalRecord{}, false, nil
522		}
523		return toProposalRecord(p), true, nil
524	}
525	
526	// Proposals 返回全部已登记提案，按编号排序。
527	func (s *Store) Proposals() ([]ProposalRecord, error) {
528		state, err := s.readState()
529		if err != nil {
530			return nil, err
531		}
532		out := make([]ProposalRecord, 0, len(state.Proposals))
533		for _, p := range state.Proposals {
534			out = append(out, toProposalRecord(p))
535		}
536		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
537		return out, nil
538	}
539	
540	func toProposalRecord(p *storedProposal) ProposalRecord {
541		return ProposalRecord{
542			ID:          p.ID,
543			State:       p.State,
544			TimelockEnd: p.TimelockEnd,
545			Actions:     copyActions(p.Actions),
546		}
547	}
548	
549	// Receipt 按编号返回执行凭据；尚未成功执行或不存在时 ok 为 false。
550	func (s *Store) Receipt(id string) (*Receipt, bool, error) {
551		state, err := s.readState()
552		if err != nil {
553			return nil, false, err
554		}
555		r := findReceipt(state.Receipts, id)
556		if r == nil {
557			return nil, false, nil
558		}
559		return cloneReceipt(r), true, nil
560	}
561	
562	// Receipts 按成功提交的先后顺序返回全部执行凭据的副本。
563	func (s *Store) Receipts() ([]*Receipt, error) {
564		state, err := s.readState()
565		if err != nil {
566			return nil, err
567		}
568		out := make([]*Receipt, 0, len(state.Receipts))
569		for _, r := range state.Receipts {
570			out = append(out, cloneReceipt(r))
571		}
572		return out, nil
573	}
574	
575	func (s *Store) readState() (*storedState, error) {
576		commit, err := s.begin()
577		if err != nil {
578			return nil, err
579		}
580		defer commit()
581		return s.loadLocked()
582	}
583	
584	// ---- 持久化 ----
585	
586	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
587	func (s *Store) loadLocked() (*storedState, error) {
588		raw, err := os.ReadFile(s.path)
589		if err != nil {
590			return nil, err
591		}
592		if len(bytes.TrimSpace(raw)) == 0 {
593			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
594		}
595		if err := rejectDuplicateKeys(raw); err != nil {
596			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
597		}
598		var state storedState
599		dec := json.NewDecoder(bytes.NewReader(raw))
600		dec.DisallowUnknownFields()
601		if err := dec.Decode(&state); err != nil {
602			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
603		}
604		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
605		var extra json.RawMessage
606		if err := dec.Decode(&extra); err != io.EOF {
607			if err == nil {
608				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
609			}
610			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
611		}
612		if err := validateState(&state); err != nil {
613			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
614		}
615		return &state, nil
616	}
617	
618	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
619	// 任一步失败都保留上次完整状态。调用方必须持锁。
620	func (s *Store) commitLocked(state *storedState) error {
621		if err := validateState(state); err != nil {
622			return fmt.Errorf("refusing to persist invalid state: %w", err)
623		}
624		payload, err := json.MarshalIndent(state, "", "  ")
625		if err != nil {
626			return err
627		}
628		payload = append(payload, '\n')
629	
630		dir := filepath.Dir(s.path)
631		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
632		if err != nil {
633			return err
634		}
635		tmpName := tmp.Name()
636		cleanup := func() { _ = os.Remove(tmpName) }
637		if _, err := tmp.Write(payload); err != nil {
638			_ = tmp.Close()
639			cleanup()
640			return err
641		}
642		if err := tmp.Sync(); err != nil {
643			_ = tmp.Close()
644			cleanup()
645			return err
646		}
647		if err := tmp.Close(); err != nil {
648			cleanup()
649			return err
650		}
651		if err := os.Chmod(tmpName, 0o600); err != nil {
652			cleanup()
653			return err
654		}
655		if err := os.Rename(tmpName, s.path); err != nil {
656			cleanup()
657			return err
658		}
659		if err := syncDir(dir); err != nil {
660			return err
661		}
662		return nil
663	}
664	
665	func syncDir(dir string) error {
666		d, err := os.Open(dir)
667		if err != nil {
668			return err
669		}
670		defer d.Close()
671		return d.Sync()
672	}
673	
674	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
675	func validateState(state *storedState) error {
676		if state.Magic != stateMagic {
677			return fmt.Errorf("bad magic %q", state.Magic)
678		}
679		if state.Version != stateVersion {
680			return fmt.Errorf("unsupported state version %d", state.Version)
681		}
682		if state.InitialTreasury < 0 {
683			return errors.New("initial treasury balance is negative")
684		}
685		if state.Treasury < 0 {
686			return errors.New("treasury balance is negative")
687		}
688		if state.Balances == nil {
689			return errors.New("balances table is missing")
690		}
691		if state.Proposals == nil {
692			return errors.New("proposals table is missing")
693		}
694		if state.Receipts == nil {
695			return errors.New("receipts table is missing")
696		}
697		for account, balance := range state.Balances {
698			if account == "" {
699				return errors.New("balance entry with empty account")
700			}
701			if balance < 0 {
702				return fmt.Errorf("balance of %q is negative", account)
703			}
704		}
705		for key, p := range state.Proposals {
706			if p == nil {
707				return fmt.Errorf("proposal %q is empty", key)
708			}
709			if p.ID != key || p.ID == "" {
710				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
711			}
712			if p.State != "passed" && p.State != "executed" {
713				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
714			}
715			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
716		}
717	
718		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
719		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
720		simTreasury := state.InitialTreasury
721		simBalances := map[string]int64{}
722		seenReceipts := map[string]int{}
723		for order, rcpt := range state.Receipts {
724			if rcpt == nil {
725				return fmt.Errorf("receipt %d is empty", order)
726			}
727			if rcpt.Order != order {
728				return fmt.Errorf("receipt %q order field is %d, expected %d", rcpt.ProposalID, rcpt.Order, order)
729			}
730			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
731				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
732			}
733			seenReceipts[rcpt.ProposalID] = order
734			proposal, ok := state.Proposals[rcpt.ProposalID]
735			if !ok {
736				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
737			}
738			if proposal.State != "executed" {
739				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, proposal.State)
740			}
741			if len(rcpt.Actions) != len(proposal.Actions) {
742				return fmt.Errorf("receipt %q action count %d does not match proposal %d", rcpt.ProposalID, len(rcpt.Actions), len(proposal.Actions))
743			}
744			for i, ar := range rcpt.Actions {
745				if ar.Index != i {
746					return fmt.Errorf("receipt %q action %d has index %d", rcpt.ProposalID, i, ar.Index)
747				}
748				if ar.Action != proposal.Actions[i] {
749					return fmt.Errorf("receipt %q action %d text does not match registered action", rcpt.ProposalID, i)
750				}
751				account, amount, err := ParseTransfer(ar.Action)
752				if err != nil {
753					return fmt.Errorf("receipt %q action %d is not executable: %v", rcpt.ProposalID, i, err)
754				}
755				if ar.Treasury.Account != "treasury" || ar.Treasury.Before != simTreasury {
756					return fmt.Errorf("receipt %q action %d treasury before-balance mismatch", rcpt.ProposalID, i)
757				}
758				if simTreasury < amount || ar.Treasury.After != simTreasury-amount {
759					return fmt.Errorf("receipt %q action %d treasury after-balance mismatch", rcpt.ProposalID, i)
760				}
761				before := simBalances[account]
762				if ar.Recipient.Account != account || ar.Recipient.Before != before {
763					return fmt.Errorf("receipt %q action %d recipient before-balance mismatch", rcpt.ProposalID, i)
764				}
765				after, ok := addInt64(before, amount)
766				if !ok || ar.Recipient.After != after {
767					return fmt.Errorf("receipt %q action %d recipient after-balance mismatch", rcpt.ProposalID, i)
768				}
769				simTreasury -= amount
770				simBalances[account] = after
771			}
772		}
773		if simTreasury != state.Treasury {
774			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
775		}
776		if len(simBalances) != len(state.Balances) {
777			return fmt.Errorf("balance table has %d accounts, receipt replay yields %d", len(state.Balances), len(simBalances))
778		}
779		for account, balance := range state.Balances {
780			if simBalances[account] != balance {
781				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
782			}
783		}
784		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
785		for _, p := range state.Proposals {
786			_, hasReceipt := seenReceipts[p.ID]
787			if p.State == "executed" && !hasReceipt {
788				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
789			}
790		}
791		return nil
792	}
793	
794	// scanFrame 是重复键扫描的栈帧。
795	type scanFrame struct {
796		isArray bool
797		seen    map[string]bool
798		atValue bool // 对象帧：下一个待消费 token 是值而非键
799	}
800	
801	func rejectDuplicateKeys(raw []byte) error {
802		dec := json.NewDecoder(bytes.NewReader(raw))
803		var stack []*scanFrame
804		for {
805			tok, err := dec.Token()
806			if err == io.EOF {
807				if len(stack) != 0 {
808					return errors.New("unterminated object or array")
809				}
810				return nil
811			}
812			if err != nil {
813				return err
814			}
815			switch t := tok.(type) {
816			case json.Delim:
817				switch t {
818				case '{':
819					stack = append(stack, &scanFrame{seen: map[string]bool{}})
820					continue
821				case '[':
822					stack = append(stack, &scanFrame{isArray: true})
823					continue
824				case '}', ']':
825					if len(stack) == 0 {
826						return errors.New("unexpected closing delimiter")
827					}
828					stack = stack[:len(stack)-1]
829					// 关闭的容器本身是外层对象的某个“值”，消费完毕后外层等待下一个键。
830					if len(stack) > 0 && !stack[len(stack)-1].isArray {
831						stack[len(stack)-1].atValue = false
832					}
833					continue
834				}
835			default:
836				// 标量 token。
837			}
838			if len(stack) > 0 && !stack[len(stack)-1].isArray {
839				frame := stack[len(stack)-1]
840				if !frame.atValue {
841					key, ok := tok.(string)
842					if !ok {
843						return errors.New("object key must be a string")
844					}
845					if frame.seen[key] {
846						return fmt.Errorf("duplicate key %q", key)
847					}
848					frame.seen[key] = true
849					frame.atValue = true
850				} else {
851					frame.atValue = false
852				}
853			}
854		}
855	}
